#include <stdlib.h>
#include <string.h>
#ifdef _OPENMP
#include <omp.h>
#endif

#if defined(__AVX512F__)
#define VL 16
#define MR 12
#define MC (MR * 8)
#else
#define VL 8
#define MR 6
#define MC (MR * 16)
#endif
#define NR (2 * VL)
#define KC 256

typedef float vf __attribute__((vector_size(VL * 4), aligned(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        acc[i][0] = (vf){0};
        acc[i][1] = (vf){0};
    }
    int k = 0;
    for (; k + 4 <= kc; k += 4) {
#pragma GCC unroll 4
        for (int u = 0; u < 4; u++) {
            vf b0 = *(const vf *)(b + u * NR);
            vf b1 = *(const vf *)(b + u * NR + VL);
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++) {
                float ai = a[u * MR + i];
                acc[i][0] += ai * b0;
                acc[i][1] += ai * b1;
            }
        }
        a += 4 * MR;
        b += 4 * NR;
    }
    for (; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            acc[i][0] += ai * b0;
            acc[i][1] += ai * b1;
        }
        a += MR;
        b += NR;
    }
    if (first) {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) = acc[i][0];
            *(vfu *)(c + i * ldc + VL) = acc[i][1];
        }
    } else {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) += acc[i][0];
            *(vfu *)(c + i * ldc + VL) += acc[i][1];
        }
    }
}

/* Pack MR rows of A (cols p0..p0+kc) into a contiguous kc x MR block. */
static void pack_a_panel(const float *A, int n, int i0, int mr, int p0, int kc, float *ap)
{
    const float *rows[MR];
    for (int i = 0; i < MR; i++)
        rows[i] = A + (size_t)(i0 + (i < mr ? i : 0)) * n + p0;
    if (mr == MR) {
        for (int k = 0; k < kc; k++)
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++)
                ap[k * MR + i] = rows[i][k];
    } else {
        for (int k = 0; k < kc; k++)
            for (int i = 0; i < MR; i++)
                ap[k * MR + i] = i < mr ? rows[i][k] : 0.0f;
    }
}

static void pack_b_panel(const float *B, int n, int p0, int kc, int j0, int nr, float *bp)
{
    if (nr == NR) {
        for (int k = 0; k < kc; k++)
            memcpy(bp + (size_t)k * NR, B + (size_t)(p0 + k) * n + j0, NR * sizeof(float));
        return;
    }
    for (int k = 0; k < kc; k++) {
        const float *src = B + (size_t)(p0 + k) * n + j0;
        float *dst = bp + (size_t)k * NR;
        int j;
        for (j = 0; j < nr; j++) dst[j] = src[j];
        for (; j < NR; j++) dst[j] = 0.0f;
    }
}

static float *g_ap = NULL, *g_bp = NULL;
static size_t g_asz = 0, g_bsz = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    need = (need + 4095) / 4096 * 4096;
    p = (float *)aligned_alloc(4096, need);
    *cap = need;
    return p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    int npanA = (n + MR - 1) / MR;
    int npanB = (n + NR - 1) / NR;
    g_ap = grow(g_ap, &g_asz, (size_t)npanA * MR * n * sizeof(float));
    g_bp = grow(g_bp, &g_bsz, (size_t)npanB * NR * n * sizeof(float));
    float *ap = g_ap, *bp = g_bp;

    int nt = 1;
#ifdef _OPENMP
    nt = omp_get_max_threads();
#endif
    int nib = (n + MC - 1) / MC;
    int target = 4 * nt;
    int njb = (target + nib - 1) / nib;
    if (njb > npanB) njb = npanB;
    if (njb < 1) njb = 1;
    int ppj = (npanB + njb - 1) / njb;
    njb = (npanB + ppj - 1) / ppj;
    int ntask = nib * njb;

    int npc = (n + KC - 1) / KC;
    int nunit = npanA + npanB;

#pragma omp parallel
    {
        float tile[MR * NR] __attribute__((aligned(64)));

        /* Pack all of A and B once, K-blocked: block for pc starts at pc*npan*width. */
#pragma omp for schedule(dynamic, 2)
        for (int u = 0; u < npc * nunit; u++) {
            int pc = (u / nunit) * KC;
            int kc = n - pc < KC ? n - pc : KC;
            int r = u % nunit;
            if (r < npanA) {
                int i0 = r * MR;
                int mr = n - i0 < MR ? n - i0 : MR;
                pack_a_panel(A, n, i0, mr, pc, kc,
                             ap + (size_t)pc * npanA * MR + (size_t)r * kc * MR);
            } else {
                int q = r - npanA;
                int j0 = q * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                pack_b_panel(B, n, pc, kc, j0, nr,
                             bp + (size_t)pc * npanB * NR + (size_t)q * kc * NR);
            }
        }

#pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntask; t++) {
            int ib = t / njb, jb = t % njb;
            int i0 = ib * MC;
            int mc = n - i0 < MC ? n - i0 : MC;
            int q0 = jb * ppj;
            int q1 = q0 + ppj < npanB ? q0 + ppj : npanB;
            for (int pc = 0; pc < n; pc += KC) {
                int kc = n - pc < KC ? n - pc : KC;
                int first = (pc == 0);
                const float *ablk = ap + (size_t)pc * npanA * MR;
                const float *bblk = bp + (size_t)pc * npanB * NR;
                for (int q = q0; q < q1; q++) {
                    int j = q * NR;
                    int nr = n - j < NR ? n - j : NR;
                    const float *bpan = bblk + (size_t)q * kc * NR;
                    for (int i = 0; i < mc; i += MR) {
                        int mr = mc - i < MR ? mc - i : MR;
                        const float *apan = ablk + (size_t)((i0 + i) / MR) * kc * MR;
                        float *cp = C + (size_t)(i0 + i) * n + j;
                        if (mr == MR && nr == NR) {
                            kernel(kc, apan, bpan, cp, n, first);
                        } else {
                            kernel(kc, apan, bpan, tile, NR, 1);
                            for (int ii = 0; ii < mr; ii++) {
                                float *crow = cp + (size_t)ii * n;
                                const float *trow = tile + ii * NR;
                                if (first)
                                    for (int jj = 0; jj < nr; jj++) crow[jj] = trow[jj];
                                else
                                    for (int jj = 0; jj < nr; jj++) crow[jj] += trow[jj];
                            }
                        }
                    }
                }
            }
        }
    }
}
